   115  Result BinaryReaderObjdumpBase::BeginModule(uint32_t version) {
   116    switch (options_->mode) {
   117      case ObjdumpMode::Headers:
   118        printf("\n");
   119        printf("Sections:\n\n");
   120        break;
   121      case ObjdumpMode::Details:
   122        printf("\n");
   123        printf("Section Details:\n\n");
   124        break;
   125      case ObjdumpMode::Disassemble:
   126        printf("\n");
   127        printf("Code Disassembly:\n\n");
   128        break;
   129      case ObjdumpMode::Prepass: {
   130        std::string_view basename = GetBasename(options_->filename);
   131        if (basename == "-") {
   132          basename = "<stdin>";
   133        }
   134        printf("%s:\tfile format wasm %#x\n", std::string(basename).c_str(),
   135               version);
   136        break;
   137      }
   138      case ObjdumpMode::RawData:
   139        break;
   140    }
   141
   142    return Result::Ok;
   143  }
