   179  std::string_view BinaryReaderObjdumpBase::GetSymbolName(
   180      Index symbol_index) const {
   181    if (symbol_index >= objdump_state_->symtab.size())
   182      return "<illegal_symbol_index>";
   183    ObjdumpSymbol& sym = objdump_state_->symtab[symbol_index];
   184    switch (sym.kind) {
   185      case SymbolType::Function:
   186        return GetFunctionName(sym.index);
   187      case SymbolType::Data:
   188        return sym.name;
   189      case SymbolType::Global:
   190        return GetGlobalName(sym.index);
   191      case SymbolType::Section:
   192        return GetSectionName(sym.index);
   193      case SymbolType::Tag:
   194        return GetTagName(sym.index);
   195      case SymbolType::Table:
   196        return GetTableName(sym.index);
   197    }
   198    WABT_UNREACHABLE;
   199  }
