   201  void BinaryReaderObjdumpBase::PrintRelocation(const Reloc& reloc,
   202                                                Offset offset) const {
   203    printf("           %06" PRIzx ": %-18s %" PRIindex, offset,
   204           GetRelocTypeName(reloc.type), reloc.index);
   205    if (reloc.addend) {
   206      printf(" + %d", reloc.addend);
   207    }
   208    if (reloc.type != RelocType::TypeIndexLEB) {
   209      printf(" <" PRIstringview ">",
   210             WABT_PRINTF_STRING_VIEW_ARG(GetSymbolName(reloc.index)));
   211    }
   212    printf("\n");
   213  }
