   226  Result BinaryReaderObjdumpBase::OnRelocCount(Index count, Index section_index) {
   227    if (section_index >= section_types_.size()) {
   228      err_stream_->Writef("invalid relocation section index: %" PRIindex "\n",
   229                          section_index);
   230      reloc_section_ = BinarySection::Invalid;
   231      return Result::Error;
   232    }
   233    reloc_section_ = section_types_[section_index];
   234    return Result::Ok;
