   503  Result BinaryReaderObjdumpPrepass::OnReloc(RelocType type,
   504                                             Offset offset,
   505                                             Index index,
   506                                             uint32_t addend) {
   507    BinaryReaderObjdumpBase::OnReloc(type, offset, index, addend);
   508    if (reloc_section_ == BinarySection::Code) {
   509      objdump_state_->code_relocations.emplace_back(type, offset, index, addend);
   510    } else if (reloc_section_ == BinarySection::Data) {
   511      objdump_state_->data_relocations.emplace_back(type, offset, index, addend);
   512    }
   513    return Result::Ok;
