   568  std::string BinaryReaderObjdumpDisassemble::BlockSigToString(Type type) const {
   569    if (type.IsIndex()) {
   570      return StringPrintf("type[%d]", type.GetIndex());
   571    } else if (type == Type::Void) {
   572      return "";
   573    } else {
   574      return type.GetName();
